package in.recallradar;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
enum RecallStatus { OPEN, REVIEWING, CONTAINED, CLOSED }
@Entity @Table(name="recall_case") class RecallCase {@Id UUID id;UUID organizationId;UUID sourceLotId;String title;@Enumerated(EnumType.STRING) RecallStatus status;UUID containmentIncidentId;Instant createdAt;UUID createdBy;protected RecallCase(){}RecallCase(UUID org,UUID lot,String title,UUID actor){id=UUID.randomUUID();organizationId=org;sourceLotId=lot;this.title=title;status=RecallStatus.OPEN;createdAt=Instant.now();createdBy=actor;}}
@Entity @Table(name="recall_impact_snapshot") class RecallImpactSnapshot {@Id UUID id;UUID recallCaseId;UUID productionBatchId;UUID locationId;String productName;String batchNumber;BigDecimal affectedQuantity;Instant capturedAt;protected RecallImpactSnapshot(){}RecallImpactSnapshot(UUID recall,UUID production,UUID location,String product,String batch,BigDecimal quantity){id=UUID.randomUUID();recallCaseId=recall;productionBatchId=production;locationId=location;productName=product;batchNumber=batch;affectedQuantity=quantity;capturedAt=Instant.now();}}
